-- Public Days 1–5 question catalogue. No answer keys or explanations are stored here.

insert into public.quizzes(id,lesson_id,title_en,title_hi,pass_percent,published)
select '50000000-0000-4000-8000-000000000001',l.id,'Day 1 Knowledge Check','दिन 1 ज्ञान जाँच',70,true from public.lessons l where l.day_number=1
on conflict(id) do update set published=true;
insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000011','50000000-0000-4000-8000-000000000001',1,'Which statement correctly separates the Internet from the World Wide Web?','कौन-सा कथन Internet और World Wide Web का सही अंतर बताता है?','[{"id":"b","label_en":"The Web connects routers; the Internet is a collection of web pages.","label_hi":"Web routers को जोड़ता है; Internet web pages का समूह है।"},{"id":"c","label_en":"The Internet only carries email; the Web carries every other kind of data.","label_hi":"Internet केवल email ले जाता है; Web बाकी सभी तरह का data ले जाता है।"},{"id":"a","label_en":"The Internet connects networks; the Web is a service of linked resources that uses it.","label_hi":"Internet networks को जोड़ता है; Web उस पर चलने वाली linked resources की service है।"},{"id":"d","label_en":"The Internet and the Web are two names for the same thing.","label_hi":"Internet और Web एक ही चीज़ के दो नाम हैं।"}]'::jsonb)
on conflict(id) do update set quiz_id=excluded.quiz_id,position=excluded.position,prompt_en=excluded.prompt_en,prompt_hi=excluded.prompt_hi,options=excluded.options;
insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000012','50000000-0000-4000-8000-000000000001',2,'A browser opens https://learn.example/courses/html?level=beginner#forms. Which part is the fragment?','Browser https://learn.example/courses/html?level=beginner#forms खोलता है। इसमें fragment कौन-सा हिस्सा है?','[{"id":"d","label_en":"forms","label_hi":"forms"},{"id":"a","label_en":"/courses/html","label_hi":"/courses/html"},{"id":"b","label_en":"learn.example","label_hi":"learn.example"},{"id":"c","label_en":"level=beginner","label_hi":"level=beginner"}]'::jsonb)
on conflict(id) do update set quiz_id=excluded.quiz_id,position=excluded.position,prompt_en=excluded.prompt_en,prompt_hi=excluded.prompt_hi,options=excluded.options;
insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000013','50000000-0000-4000-8000-000000000001',3,'What normally happens after a browser receives an HTML response from a server?','Server से HTML response मिलने के बाद सामान्यतः browser क्या करता है?','[{"id":"a","label_en":"It assumes every linked file is already inside the HTML.","label_hi":"वह मान लेता है कि सभी linked files HTML में पहले से मौजूद हैं।"},{"id":"c","label_en":"It sends the HTML to DNS to translate it into an IP address.","label_hi":"वह HTML को IP address में बदलने के लिए DNS को वापस भेजता है।"},{"id":"d","label_en":"It changes the server''s HTTP status code to 200.","label_hi":"वह server का HTTP status code 200 कर देता है।"},{"id":"b","label_en":"It parses the HTML and requests linked resources such as CSS, scripts and images.","label_hi":"वह HTML parse करता है और CSS, scripts तथा images जैसे linked resources माँगता है।"}]'::jsonb)
on conflict(id) do update set quiz_id=excluded.quiz_id,position=excluded.position,prompt_en=excluded.prompt_en,prompt_hi=excluded.prompt_hi,options=excluded.options;
insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000014','50000000-0000-4000-8000-000000000001',4,'What does this response status mean: HTTP/1.1 404 Not Found?','इस response status का क्या अर्थ है: HTTP/1.1 404 Not Found?','[{"id":"a","label_en":"The request succeeded and the resource was returned.","label_hi":"Request सफल हुई और resource मिल गया।"},{"id":"c","label_en":"The requested resource could not be found at that URL.","label_hi":"उस URL पर माँगा गया resource नहीं मिला।"},{"id":"b","label_en":"The browser must sign in before continuing.","label_hi":"आगे बढ़ने से पहले browser को sign in करना होगा।"},{"id":"d","label_en":"The server permanently moved the resource to a new URL.","label_hi":"Server ने resource को स्थायी रूप से नए URL पर भेज दिया।"}]'::jsonb)
on conflict(id) do update set quiz_id=excluded.quiz_id,position=excluded.position,prompt_en=excluded.prompt_en,prompt_hi=excluded.prompt_hi,options=excluded.options;

insert into public.quizzes(id,lesson_id,title_en,title_hi,pass_percent,published)
select '50000000-0000-4000-8000-000000000002',l.id,'Day 2 Knowledge Check','दिन 2 ज्ञान जाँच',70,true from public.lessons l where l.day_number=2
on conflict(id) do update set published=true;
insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000021','50000000-0000-4000-8000-000000000002',1,'In an HTML document, where should the page title and character-encoding declaration normally be placed?','HTML document में page title और character-encoding declaration सामान्यतः कहाँ होने चाहिए?','[{"id":"b","label_en":"Inside the footer element","label_hi":"footer element के अंदर"},{"id":"a","label_en":"Inside the head element","label_hi":"head element के अंदर"},{"id":"c","label_en":"After the closing html tag","label_hi":"closing html tag के बाद"},{"id":"d","label_en":"Inside every paragraph element","label_hi":"हर paragraph element के अंदर"}]'::jsonb)
on conflict(id) do update set quiz_id=excluded.quiz_id,position=excluded.position,prompt_en=excluded.prompt_en,prompt_hi=excluded.prompt_hi,options=excluded.options;
insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000022','50000000-0000-4000-8000-000000000002',2,'A page has one main heading and two section headings. Which heading structure expresses that hierarchy correctly?','Page में एक मुख्य heading और दो section headings हैं। कौन-सी heading structure यह hierarchy सही दिखाती है?','[{"id":"a","label_en":"Use h1 for the page title and h2 for each section heading.","label_hi":"Page title के लिए h1 और हर section heading के लिए h2 इस्तेमाल करें।"},{"id":"c","label_en":"Use h3 for the page title and h2 for the section headings.","label_hi":"Page title के लिए h3 और section headings के लिए h2 इस्तेमाल करें।"},{"id":"d","label_en":"Use paragraph elements for all headings and style them visually.","label_hi":"सभी headings के लिए paragraph elements इस्तेमाल करें और उन्हें केवल style करें।"},{"id":"b","label_en":"Use h2 for the page title and h1 for both section headings.","label_hi":"Page title के लिए h2 और दोनों section headings के लिए h1 इस्तेमाल करें।"}]'::jsonb)
on conflict(id) do update set quiz_id=excluded.quiz_id,position=excluded.position,prompt_en=excluded.prompt_en,prompt_hi=excluded.prompt_hi,options=excluded.options;
insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000023','50000000-0000-4000-8000-000000000002',3,'A page needs a navigation landmark for its primary site links. Which element is the best semantic choice?','Page के मुख्य site links के लिए navigation landmark चाहिए। कौन-सा element सही semantic choice है?','[{"id":"c","label_en":"<nav>","label_hi":"<nav>"},{"id":"a","label_en":"<div>","label_hi":"<div>"},{"id":"b","label_en":"<span>","label_hi":"<span>"},{"id":"d","label_en":"<aside>","label_hi":"<aside>"}]'::jsonb)
on conflict(id) do update set quiz_id=excluded.quiz_id,position=excluded.position,prompt_en=excluded.prompt_en,prompt_hi=excluded.prompt_hi,options=excluded.options;
insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000024','50000000-0000-4000-8000-000000000002',4,'Which change fixes this document-language issue? <html lang="">','इस document-language issue को कौन-सा बदलाव ठीक करता है? <html lang="">','[{"id":"a","label_en":"Add lang to body and leave html empty.","label_hi":"body में lang जोड़ें और html खाली छोड़ें।"},{"id":"b","label_en":"Replace lang with charset.","label_hi":"lang को charset से बदलें।"},{"id":"d","label_en":"Set a valid language tag, for example <html lang=\"en\">.","label_hi":"एक valid language tag सेट करें, जैसे <html lang=\"en\">।"},{"id":"c","label_en":"Put the language only in a CSS class.","label_hi":"Language केवल CSS class में लिखें।"}]'::jsonb)
on conflict(id) do update set quiz_id=excluded.quiz_id,position=excluded.position,prompt_en=excluded.prompt_en,prompt_hi=excluded.prompt_hi,options=excluded.options;

