insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000031','50000000-0000-4000-8000-000000000003',1,'Which attribute should contain a hyperlink''s destination address?','Hyperlink का destination address किस attribute में होना चाहिए?','[{"id":"b","label_en":"The src attribute on a p element","label_hi":"p element के src attribute में"},{"id":"c","label_en":"The alt attribute on a link element","label_hi":"link element के alt attribute में"},{"id":"d","label_en":"The action attribute on a heading","label_hi":"heading के action attribute में"},{"id":"a","label_en":"The href attribute on an a element","label_hi":"a element के href attribute में"}]'::jsonb)
