insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000032','50000000-0000-4000-8000-000000000003',2,'What is the browser''s default meaning of <ol><li>Tea</li><li>Coffee</li></ol>?','<ol><li>Tea</li><li>Coffee</li></ol> का browser में सामान्य अर्थ क्या है?','[{"id":"a","label_en":"Two unrelated paragraphs","label_hi":"दो असंबंधित paragraphs"},{"id":"b","label_en":"An ordered list with two items","label_hi":"दो items वाली ordered list"},{"id":"c","label_en":"A table with two columns","label_hi":"दो columns वाली table"},{"id":"d","label_en":"A navigation menu that automatically opens links","label_hi":"ऐसा navigation menu जो links अपने आप खोलता है"}]'::jsonb)
