insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000033','50000000-0000-4000-8000-000000000003',3,'A link should open the user''s email app to write to help@example.com. Which href value is appropriate?','एक link को help@example.com पर email लिखने के लिए user''s email app खोलना है। कौन-सी href value सही है?','[{"id":"a","label_en":"https://help@example.com","label_hi":"https://help@example.com"},{"id":"b","label_en":"src=\"mailto:help@example.com\"","label_hi":"src=\"mailto:help@example.com\""},{"id":"c","label_en":"mailto:help@example.com","label_hi":"mailto:help@example.com"},{"id":"d","label_en":"email:help@example.com","label_hi":"email:help@example.com"}]'::jsonb)
on conflict(id) do update set quiz_id=excluded.quiz_id,position=excluded.position,prompt_en=excluded.prompt_en,prompt_hi=excluded.prompt_hi,options=excluded.options;
insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000034','50000000-0000-4000-8000-000000000003',4,'A paragraph needs to mark one word as strongly important. Which markup is most appropriate?','एक paragraph में एक शब्द को strong importance देनी है। कौन-सा markup सबसे उपयुक्त है?','[{"id":"d","label_en":"<strong>important</strong>","label_hi":"<strong>important</strong>"},{"id":"a","label_en":"<small>important</small>","label_hi":"<small>important</small>"},{"id":"b","label_en":"<mark>important</mark>","label_hi":"<mark>important</mark>"},{"id":"c","label_en":"<i>important</i>","label_hi":"<i>important</i>"}]'::jsonb)
on conflict(id) do update set quiz_id=excluded.quiz_id,position=excluded.position,prompt_en=excluded.prompt_en,prompt_hi=excluded.prompt_hi,options=excluded.options;

