insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000041','50000000-0000-4000-8000-000000000004',1,'Which attribute gives a meaningful text alternative for an informative image?','Informative image के लिए meaningful text alternative कौन-सा attribute देता है?','[{"id":"b","label_en":"alt","label_hi":"alt"},{"id":"a","label_en":"title","label_hi":"title"},{"id":"c","label_en":"href","label_hi":"href"},{"id":"d","label_en":"width","label_hi":"width"}]'::jsonb)
