insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000042','50000000-0000-4000-8000-000000000004',2,'Which markup gives a browser native playback controls for an audio file?','Audio file के लिए browser के native playback controls कौन-सा markup देता है?','[{"id":"a","label_en":"<img controls src=\"sound.mp3\">","label_hi":"<img controls src=\"sound.mp3\">"},{"id":"b","label_en":"<video controls src=\"sound.mp3\"></video>","label_hi":"<video controls src=\"sound.mp3\"></video>"},{"id":"c","label_en":"<audio controls src=\"sound.mp3\"></audio>","label_hi":"<audio controls src=\"sound.mp3\"></audio>"},{"id":"d","label_en":"<source controls src=\"sound.mp3\">","label_hi":"<source controls src=\"sound.mp3\">"}]'::jsonb)
