insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000043','50000000-0000-4000-8000-000000000004',3,'A decorative divider image adds no information. Which alt value is normally appropriate?','एक decorative divider image कोई जानकारी नहीं देती। सामान्यतः कौन-सी alt value सही है?','[{"id":"b","label_en":"alt=\"decorative divider image\"","label_hi":"alt=\"decorative divider image\""},{"id":"a","label_en":"alt=\"\"","label_hi":"alt=\"\""},{"id":"c","label_en":"alt=\"divider.png\"","label_hi":"alt=\"divider.png\""},{"id":"d","label_en":"alt=\"image\"","label_hi":"alt=\"image\""}]'::jsonb)
on conflict(id) do update set quiz_id=excluded.quiz_id,position=excluded.position,prompt_en=excluded.prompt_en,prompt_hi=excluded.prompt_hi,options=excluded.options;
insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000044','50000000-0000-4000-8000-000000000004',4,'Which markup provides native browser controls for a video file?','Video file के लिए browser के native controls कौन-सा markup देता है?','[{"id":"a","label_en":"<audio controls src=\"clip.mp4\"></audio>","label_hi":"<audio controls src=\"clip.mp4\"></audio>"},{"id":"b","label_en":"<img controls src=\"clip.mp4\">","label_hi":"<img controls src=\"clip.mp4\">"},{"id":"c","label_en":"<source controls src=\"clip.mp4\">","label_hi":"<source controls src=\"clip.mp4\">"},{"id":"d","label_en":"<video controls src=\"clip.mp4\"></video>","label_hi":"<video controls src=\"clip.mp4\"></video>"}]'::jsonb)
