insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000051','50000000-0000-4000-8000-000000000005',1,'Which markup correctly connects a visible label to an email input?','कौन-सा markup visible label को email input से सही तरह जोड़ता है?','[{"id":"a","label_en":"<label>Email</label><input type=\"email\">","label_hi":"<label>Email</label><input type=\"email\">"},{"id":"c","label_en":"<input type=\"email\" label=\"Email\">","label_hi":"<input type=\"email\" label=\"Email\">"},{"id":"b","label_en":"<label for=\"email\">Email</label><input id=\"email\" type=\"email\">","label_hi":"<label for=\"email\">Email</label><input id=\"email\" type=\"email\">"},{"id":"d","label_en":"<p>Email</p><input type=\"email\" placeholder=\"Email\">","label_hi":"<p>Email</p><input type=\"email\" placeholder=\"Email\">"}]'::jsonb)
on conflict(id) do update set quiz_id=excluded.quiz_id,position=excluded.position,prompt_en=excluded.prompt_en,prompt_hi=excluded.prompt_hi,options=excluded.options;
insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000052','50000000-0000-4000-8000-000000000005',2,'What happens when a required email input is empty and the user submits a normal browser-validated form?','जब required email input खाली हो और user सामान्य browser-validated form submit करे, तो क्या होता है?','[{"id":"b","label_en":"The browser automatically invents an email address.","label_hi":"Browser अपने आप email address बना देता है।"},{"id":"c","label_en":"The browser silently changes the input type to text.","label_hi":"Browser चुपचाप input type को text कर देता है।"},{"id":"d","label_en":"The browser submits the form and marks the field as valid.","label_hi":"Browser form submit करके field को valid मान लेता है।"},{"id":"a","label_en":"The browser normally blocks submission and reports a constraint validation error.","label_hi":"Browser सामान्यतः submission रोकता है और constraint validation error दिखाता है।"}]'::jsonb)
on conflict(id) do update set quiz_id=excluded.quiz_id,position=excluded.position,prompt_en=excluded.prompt_en,prompt_hi=excluded.prompt_hi,options=excluded.options;
insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000053','50000000-0000-4000-8000-000000000005',3,'A group of related radio buttons needs a shared accessible caption. Which elements should wrap the group?','Related radio buttons के group को shared accessible caption चाहिए। कौन-से elements group को wrap करें?','[{"id":"c","label_en":"fieldset and legend","label_hi":"fieldset और legend"},{"id":"a","label_en":"section and header","label_hi":"section और header"},{"id":"b","label_en":"div and span","label_hi":"div और span"},{"id":"d","label_en":"label and placeholder","label_hi":"label और placeholder"}]'::jsonb)
on conflict(id) do update set quiz_id=excluded.quiz_id,position=excluded.position,prompt_en=excluded.prompt_en,prompt_hi=excluded.prompt_hi,options=excluded.options;
insert into public.quiz_questions(id,quiz_id,position,prompt_en,prompt_hi,options)
values('60000000-0000-4000-8000-000000000054','50000000-0000-4000-8000-000000000005',4,'A search form should put a non-sensitive search term in the URL so the result can be bookmarked. Which method is the best fit?','Search form में non-sensitive search term URL में रखना है ताकि result bookmark हो सके। कौन-सा method सही है?','[{"id":"a","label_en":"POST, because it always makes data bookmarkable","label_hi":"POST, क्योंकि यह हमेशा data bookmarkable बनाता है"},{"id":"d","label_en":"GET, because form data is placed in the URL query string","label_hi":"GET, क्योंकि form data URL query string में जाता है"},{"id":"b","label_en":"PUT, because browsers require it for all forms","label_hi":"PUT, क्योंकि सभी forms के लिए browser इसे जरूरी मानता है"},{"id":"c","label_en":"PATCH, because search modifies the server","label_hi":"PATCH, क्योंकि search server को बदलता है"}]'::jsonb)
on conflict(id) do update set quiz_id=excluded.quiz_id,position=excluded.position,prompt_en=excluded.prompt_en,prompt_hi=excluded.prompt_hi,options=excluded.options;

commit;
